// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address prover, address newOwner) public {
        vm.assume(prover != address(0));
        vm.assume(newOwner != address(0));
        vm.assume(prover.code.length == 0);
        vm.assume(newOwner != address(this));

        vm.prank(address(0));
        c.transferOwnership(prover);

        vm.prank(prover);
        c.transferOwnership(newOwner);

        assertTrue(c.owner() == newOwner);
    }
}
